//! Envoy drives in the world (envoy-core-v2.md 3.1): the owner's own `envoy_drives` models (generated by
//! `pc/scripts/examples/envoy_drives/tools/make_drives.py`, original geometry and colour ramps, no game data) drawn
//! in the match, and the stand-in effects (rings, discs, spikes, bolts, beams) a fire leaves.
//!
//! Presentation only, read-only on the sim: a UI mod queues instances through `gd_ui_world_model` / `gd_ui_world_fx`
//! during its present (melee_modhost::ui); [`commit`] publishes the present's list and the fighter draw pass of slot
//! 0 ([`draw`], hooked as `ftdrawcommon::WORLD_DRAW`) draws the last committed list through GX with the current
//! camera, depth-tested: models opaque and depth-writing, then glass and effects blended without depth writes.
//! [`sprite_sheet`] rasterizes a model on the CPU (turning, `SPRITE_FRAMES` yaw steps) for the 2D cards.
//!
//! The meshes are decoded once (GXMS v2: positions, UVs, normals), normalised to a unit diameter, and coloured per
//! vertex from the shared atlas (base + glow rows); no textures reach the GPU.

use std::sync::{Mutex, OnceLock};

macro_rules! model {
    ($n:literal) => {
        include_bytes!(concat!("../../../../pc/scripts/examples/envoy_drives/models/", $n, ".gxmesh"))
    };
}

/// Model ids (gd_ui_world_model / gd_ui_model_tex): the six family bodies, the glass shell, the three ring overlays.
pub const M_GLASS: usize = 6;
pub const MODEL_COUNT: usize = 10;
static MESH_FILES: [&[u8]; MODEL_COUNT] = [
    model!("drive_red"),
    model!("drive_green"),
    model!("drive_blue"),
    model!("drive_yellow"),
    model!("drive_purple"),
    model!("drive_white"),
    model!("drive_glass"),
    model!("drive_ring_magic"),
    model!("drive_ring_rare"),
    model!("drive_ring_unique"),
];
static ATLAS: &[u8] = include_bytes!("../../../../pc/scripts/examples/envoy_drives/models/drive_atlas.gxtex");
static GLOW: &[u8] = include_bytes!("../../../../pc/scripts/examples/envoy_drives/models/drive_atlas.glow.gxtex");

/// One decoded model: triangles (3 vertices each) in unit-diameter space, normals, base and glow colours.
pub struct Baked {
    pub pos: Vec<[f32; 3]>,
    pub nrm: Vec<[f32; 3]>,
    pub base: Vec<[f32; 3]>,
    pub glow: Vec<[f32; 3]>,
}

fn be32(d: &[u8], o: usize) -> u32 {
    u32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}
fn bef(d: &[u8], o: usize) -> f32 {
    f32::from_bits(be32(d, o))
}

/// A GXTX v1 RGBA8 image (4x4 tiles: 16 AR pairs, then 16 GB pairs) as (w, h, rgba rows).
pub fn decode_gxtx(d: &[u8]) -> Option<(usize, usize, Vec<u8>)> {
    if d.len() < 64 || &d[..4] != b"GXTX" || be32(d, 8) != 6 {
        return None;
    }
    let (w, h) = (be32(d, 12) as usize, be32(d, 16) as usize);
    let off = be32(d, 36) as usize;
    if w % 4 != 0 || h % 4 != 0 || d.len() < off + w * h * 4 {
        return None;
    }
    let mut out = vec![0u8; w * h * 4];
    let mut p = off;
    for ty in (0..h).step_by(4) {
        for tx in (0..w).step_by(4) {
            for i in 0..16 {
                let (x, y) = (tx + i % 4, ty + i / 4);
                let o = (y * w + x) * 4;
                out[o + 3] = d[p + i * 2];
                out[o] = d[p + i * 2 + 1];
                out[o + 1] = d[p + 32 + i * 2];
                out[o + 2] = d[p + 32 + i * 2 + 1];
            }
            p += 64;
        }
    }
    Some((w, h, out))
}

fn sample(img: &(usize, usize, Vec<u8>), u: f32, v: f32) -> [f32; 3] {
    let (w, h, px) = img;
    let x = ((u * *w as f32) as usize).min(w - 1);
    let y = ((v * *h as f32) as usize).min(h - 1);
    let o = (y * w + x) * 4;
    [px[o] as f32 / 255.0, px[o + 1] as f32 / 255.0, px[o + 2] as f32 / 255.0]
}

/// A GXMS v2 mesh, unrolled to triangles and normalised to a unit diameter around its centre.
pub fn decode_mesh(d: &[u8], atlas: &(usize, usize, Vec<u8>), glow: &(usize, usize, Vec<u8>)) -> Option<Baked> {
    if d.len() < 36 || &d[..4] != b"GXMS" || be32(d, 4) != 2 {
        return None;
    }
    let (nv, ni) = (be32(d, 8) as usize, be32(d, 12) as usize);
    let (vo, io) = (be32(d, 28) as usize, be32(d, 32) as usize);
    if d.len() < vo + nv * 32 || d.len() < io + ni * 2 || ni % 3 != 0 {
        return None;
    }
    let vert = |i: usize| -> [f32; 8] {
        let mut v = [0f32; 8];
        for (k, x) in v.iter_mut().enumerate() {
            *x = bef(d, vo + i * 32 + k * 4);
        }
        v
    };
    let mut lo = [f32::MAX; 3];
    let mut hi = [f32::MIN; 3];
    for i in 0..nv {
        let v = vert(i);
        for k in 0..3 {
            lo[k] = lo[k].min(v[k]);
            hi[k] = hi[k].max(v[k]);
        }
    }
    let c = [(lo[0] + hi[0]) * 0.5, (lo[1] + hi[1]) * 0.5, (lo[2] + hi[2]) * 0.5];
    let size = (0..3).map(|k| hi[k] - lo[k]).fold(0.0f32, f32::max).max(1e-3);
    let mut b = Baked { pos: Vec::new(), nrm: Vec::new(), base: Vec::new(), glow: Vec::new() };
    for t in 0..ni {
        let i = u16::from_be_bytes([d[io + t * 2], d[io + t * 2 + 1]]) as usize;
        if i >= nv {
            return None;
        }
        let v = vert(i);
        b.pos.push([(v[0] - c[0]) / size, (v[1] - c[1]) / size, (v[2] - c[2]) / size]);
        b.nrm.push([v[5], v[6], v[7]]);
        b.base.push(sample(atlas, v[3], v[4]));
        b.glow.push(sample(glow, v[3], v[4]));
    }
    Some(b)
}

/// Every model, decoded once.
pub fn models() -> &'static [Baked] {
    static M: OnceLock<Vec<Baked>> = OnceLock::new();
    M.get_or_init(|| {
        let empty = (4usize, 4usize, vec![0u8; 64]);
        let atlas = decode_gxtx(ATLAS).unwrap_or_else(|| empty.clone());
        let glow = decode_gxtx(GLOW).unwrap_or(empty);
        MESH_FILES
            .iter()
            .map(|d| decode_mesh(d, &atlas, &glow).unwrap_or(Baked { pos: Vec::new(), nrm: Vec::new(), base: Vec::new(), glow: Vec::new() }))
            .collect()
    })
}

/// Lit colour of model vertex `i` turned by (yaw, pitch): base x (ambient + diffuse) + glow x `glow`.
fn shade(m: &Baked, i: usize, rot: &dyn Fn([f32; 3]) -> [f32; 3], glow: f32) -> [f32; 3] {
    const L: [f32; 3] = [0.35, 0.6, 0.72];
    let n = rot(m.nrm[i]);
    let d = (n[0] * L[0] + n[1] * L[1] + n[2] * L[2]).max(0.0);
    let k = 0.42 + 0.7 * d;
    let (b, g) = (m.base[i], m.glow[i]);
    [(b[0] * k + g[0] * glow).min(1.0), (b[1] * k + g[1] * glow).min(1.0), (b[2] * k + g[2] * glow).min(1.0)]
}

fn rotator(yaw: f32, pitch: f32) -> impl Fn([f32; 3]) -> [f32; 3] {
    let (sy, cy) = yaw.sin_cos();
    let (sp, cp) = pitch.sin_cos();
    move |p: [f32; 3]| {
        let (x, z) = (p[0] * cy + p[2] * sy, -p[0] * sy + p[2] * cy);
        let (y, z) = (p[1] * cp - z * sp, p[1] * sp + z * cp);
        [x, y, z]
    }
}

// ---- the world list (presentation, filled by the UI host each present)

/// One queued world draw.
#[derive(Clone, Copy, Debug)]
pub enum Inst {
    /// model id, centre, yaw, diameter (world units), glow 0..1, alpha 0..1
    Model { model: u8, at: [f32; 3], yaw: f32, scale: f32, glow: f32, alpha: f32 },
    /// an additive effect shape: kind, centre, three numbers, colour RGBA
    Fx { kind: u8, at: [f32; 3], a: f32, b: f32, c: f32, rgba: u32 },
}

pub const FX_RING: u8 = 1;
pub const FX_DISC: u8 = 2;
pub const FX_SPIKES: u8 = 3;
pub const FX_BOLT: u8 = 4;
pub const FX_BEAM: u8 = 5;
pub const FX_LINE: u8 = 6;

/// Per-present cap (budget: 8 orbiters + 2, a drop, a handful of effects).
pub const MAX_INST: usize = 96;

static BUILD: Mutex<Vec<Inst>> = Mutex::new(Vec::new());
static SHOW: Mutex<Vec<Inst>> = Mutex::new(Vec::new());

/// A present begins: nothing queued yet.
pub fn begin() {
    if let Ok(mut b) = BUILD.lock() {
        b.clear();
    }
}

/// Queue one draw (false: the present's cap is reached).
pub fn push(i: Inst) -> bool {
    let Ok(mut b) = BUILD.lock() else { return false };
    if b.len() >= MAX_INST {
        return false;
    }
    b.push(i);
    true
}

/// The present ended: its list is what the world draws until the next one.
pub fn commit() {
    let (Ok(mut b), Ok(mut s)) = (BUILD.lock(), SHOW.lock()) else { return };
    std::mem::swap(&mut *b, &mut *s);
    b.clear();
    if !s.is_empty() {
        // installed on the first present that queues anything: with no Envoy UI the fighter pass is untouched
        unsafe { melee_fighter::tu::ftdrawcommon::WORLD_DRAW = Some(draw) };
    }
}

/// Draws presented so far (tests, logs).
pub fn shown() -> usize {
    SHOW.lock().map_or(0, |s| s.len())
}

type Tri = ([f32; 3], [u8; 4]);

fn c8(c: [f32; 3], a: f32) -> [u8; 4] {
    let q = |v: f32| (v.clamp(0.0, 1.0) * 255.0) as u8;
    [q(c[0]), q(c[1]), q(c[2]), q(a)]
}

fn rgba_of(c: u32, k: f32) -> [u8; 4] {
    let a = ((c & 0xFF) as f32 * k.clamp(0.0, 1.0)) as u8;
    [(c >> 24) as u8, (c >> 16) as u8, (c >> 8) as u8, a]
}

fn model_tris(m: &Baked, at: [f32; 3], yaw: f32, scale: f32, glow: f32, alpha: f32, out: &mut Vec<Tri>) {
    let rot = rotator(yaw, 0.35);
    for i in 0..m.pos.len() {
        let p = rot(m.pos[i]);
        out.push(([at[0] + p[0] * scale, at[1] + p[1] * scale, at[2] + p[2] * scale], c8(shade(m, i, &rot, glow), alpha)));
    }
}

fn quad(out: &mut Vec<Tri>, a: [f32; 3], b: [f32; 3], c: [f32; 3], d: [f32; 3], ca: [u8; 4], cb: [u8; 4]) {
    out.extend_from_slice(&[(a, ca), (b, ca), (c, cb), (a, ca), (c, cb), (d, cb)]);
}

/// The effect shapes, in the stage plane (facing the camera), at `at`'s depth.
fn fx_tris(kind: u8, at: [f32; 3], a: f32, b: f32, c: f32, rgba: u32, out: &mut Vec<Tri>) {
    let col = rgba_of(rgba, 1.0);
    let clear = rgba_of(rgba, 0.0);
    let p = |x: f32, y: f32| [at[0] + x, at[1] + y, at[2]];
    match kind {
        FX_RING => {
            let (r0, r1) = ((a - b * 0.5).max(0.0), a + b * 0.5);
            for s in 0..32 {
                let (t0, t1) = (s as f32 / 32.0 * std::f32::consts::TAU, (s + 1) as f32 / 32.0 * std::f32::consts::TAU);
                let (s0, c0, s1, c1) = (t0.sin(), t0.cos(), t1.sin(), t1.cos());
                quad(out, p(c0 * r0, s0 * r0), p(c1 * r0, s1 * r0), p(c1 * r1, s1 * r1), p(c0 * r1, s0 * r1), col, col);
            }
        }
        FX_DISC => {
            for s in 0..24 {
                let (t0, t1) = (s as f32 / 24.0 * std::f32::consts::TAU, (s + 1) as f32 / 24.0 * std::f32::consts::TAU);
                out.extend_from_slice(&[(p(0.0, 0.0), col), (p(t0.cos() * a, t0.sin() * a), clear), (p(t1.cos() * a, t1.sin() * a), clear)]);
            }
        }
        FX_SPIKES => {
            let n = 8;
            for s in 0..n {
                let t = c + s as f32 / n as f32 * std::f32::consts::TAU;
                let w = 0.22;
                let (ta, tb) = (t - w, t + w);
                out.extend_from_slice(&[
                    (p(ta.cos() * a, ta.sin() * a), col),
                    (p(tb.cos() * a, tb.sin() * a), col),
                    (p(t.cos() * b, t.sin() * b), clear),
                ]);
            }
        }
        FX_BOLT | FX_LINE => {
            // from `at` to (a, b), width c; a bolt zigzags
            let (dx, dy) = (a - at[0], b - at[1]);
            let len = (dx * dx + dy * dy).sqrt().max(1e-3);
            let (nx, ny) = (-dy / len * c * 0.5, dx / len * c * 0.5);
            let segs = if kind == FX_BOLT { 7 } else { 1 };
            let mut prev = [at[0], at[1]];
            for s in 1..=segs {
                let t = s as f32 / segs as f32;
                let j = if kind == FX_BOLT && s < segs { (if s % 2 == 0 { 1.0 } else { -1.0 }) * len * 0.06 } else { 0.0 };
                let cur = [at[0] + dx * t + -dy / len * j, at[1] + dy * t + dx / len * j];
                let q = |x: f32, y: f32| [x, y, at[2]];
                quad(out, q(prev[0] + nx, prev[1] + ny), q(cur[0] + nx, cur[1] + ny), q(cur[0] - nx, cur[1] - ny), q(prev[0] - nx, prev[1] - ny), col, col);
                prev = cur;
            }
        }
        FX_BEAM => {
            // a column of height a, width b, fading upward
            let w = b * 0.5;
            quad(out, p(-w, 0.0), p(w, 0.0), p(w, a), p(-w, a), col, clear);
        }
        _ => {}
    }
}

/// The fighter draw pass hook (`ftdrawcommon::WORLD_DRAW`): slot 0's fighter, pass 0 only, so the list draws once
/// per render with that pass's camera.
pub unsafe fn draw(g: *mut melee_types::HSD_GObj, pass: i32) {
    if pass != 0 || g.is_null() || (*g).user_data.is_null() {
        return;
    }
    let f = &*((*g).user_data as *const melee_types::Fighter);
    if f.player_idx != 0 || f.is_sub_fighter() != 0 {
        return;
    }
    let Ok(list) = SHOW.lock() else { return };
    if list.is_empty() {
        return;
    }
    let ms = models();
    let mut opaque: Vec<Tri> = Vec::new();
    let mut glass: Vec<Tri> = Vec::new();
    let mut add: Vec<Tri> = Vec::new();
    for i in list.iter() {
        match *i {
            Inst::Model { model, at, yaw, scale, glow, alpha } => {
                let Some(m) = ms.get(model as usize) else { continue };
                let glassy = model as usize == M_GLASS || alpha < 0.99;
                model_tris(m, at, yaw, scale, glow, if model as usize == M_GLASS { alpha.min(0.3) } else { alpha }, if glassy { &mut glass } else { &mut opaque });
            }
            Inst::Fx { kind, at, a, b, c, rgba } => fx_tris(kind, at, a, b, c, rgba, &mut add),
        }
    }
    drop(list);
    emit(&opaque, 0);
    emit(&glass, 1);
    emit(&add, 2);
}

/// GX: a triangle list with vertex colours, depth-tested; `mode` 0 opaque (writes depth), 1 alpha blend, 2 additive.
unsafe fn emit(tris: &[Tri], mode: u32) {
    use melee_runtime::tu::displayfunc_native::ext as gx;
    use melee_types::*;
    if tris.is_empty() {
        return;
    }
    let cobj = melee_runtime::tu::cobj::HSD_CObjGetCurrent();
    if cobj.is_null() {
        return;
    }
    melee_runtime::tu::state_native::HSD_StateInvalidate(-1);
    gx::GXSetColorUpdate(1);
    gx::GXSetAlphaUpdate(0);
    match mode {
        0 => gx::GXSetBlendMode(GX_BM_NONE as _, GX_BL_ONE as _, GX_BL_ZERO as _, GX_LO_NOOP as _),
        1 => gx::GXSetBlendMode(GX_BM_BLEND as _, GX_BL_SRCALPHA as _, GX_BL_INVSRCALPHA as _, GX_LO_NOOP as _),
        _ => gx::GXSetBlendMode(GX_BM_BLEND as _, GX_BL_SRCALPHA as _, GX_BL_ONE as _, GX_LO_NOOP as _),
    }
    gx::GXSetAlphaCompare(GX_ALWAYS as _, 0, GX_AOP_AND as _, GX_ALWAYS as _, 0);
    gx::GXSetZMode(1, GX_LEQUAL as _, (mode == 0) as _);
    gx::GXSetZCompLoc(1);
    gx::GXSetNumTexGens(0);
    gx::GXSetNumTevStages(1);
    gx::GXSetTevOrder(GX_TEVSTAGE0 as _, GX_TEXCOORD_NULL as _, GX_TEXMAP_NULL as _, GX_COLOR0A0 as _);
    gx::GXSetTevOp(GX_TEVSTAGE0 as _, GX_PASSCLR as _);
    gx::GXSetNumChans(1);
    gx::GXSetChanCtrl(GX_COLOR0A0 as _, 0, GX_SRC_REG as _, GX_SRC_VTX as _, 0, GX_DF_NONE as _, GX_AF_NONE as _);
    gx::GXSetCullMode(GX_CULL_NONE as _);
    gx::GXClearVtxDesc();
    gx::GXSetVtxAttrFmt(GX_VTXFMT0 as _, GX_VA_POS as _, GX_POS_XYZ as _, GX_F32 as _, 0);
    gx::GXSetVtxAttrFmt(GX_VTXFMT0 as _, GX_VA_CLR0 as _, GX_CLR_RGBA as _, GX_RGBA8 as _, 0);
    gx::GXSetVtxDesc(GX_VA_POS as _, GX_DIRECT as _);
    gx::GXSetVtxDesc(GX_VA_CLR0 as _, GX_DIRECT as _);
    melee_runtime::tu::pobj::native::mx::GXLoadPosMtxImm((&mut (*cobj).view_mtx) as *mut Mtx as _, 0);
    gx::GXSetCurrentMtx(0);
    for chunk in tris.chunks(3 * 20000) {
        gx::GXBegin(GX_TRIANGLES as _, GX_VTXFMT0 as _, chunk.len() as _);
        for (p, c) in chunk {
            gx::GXPosition3f32(p[0], p[1], p[2]);
            gx::GXColor4u8(c[0], c[1], c[2], c[3]);
        }
    }
    melee_runtime::tu::state_native::HSD_StateInvalidate(-1);
}

// ---- sprites for the 2D cards (CPU raster)

pub const SPRITE: usize = 64;
pub const SPRITE_FRAMES: usize = 12;

/// `model` turning: SPRITE_FRAMES cells of SPRITE x SPRITE side by side (RGBA, transparent background).
pub fn sprite_sheet(model: usize) -> Option<(usize, usize, Vec<u8>)> {
    let m = models().get(model)?;
    if m.pos.is_empty() {
        return None;
    }
    let (w, h) = (SPRITE * SPRITE_FRAMES, SPRITE);
    let mut px = vec![0u8; w * h * 4];
    let mut zb = vec![f32::MIN; w * h];
    for fr in 0..SPRITE_FRAMES {
        let rot = rotator(fr as f32 / SPRITE_FRAMES as f32 * std::f32::consts::TAU, 0.35);
        let ox = (fr * SPRITE) as f32;
        let s = SPRITE as f32 * 0.86;
        let half = SPRITE as f32 * 0.5;
        for t in (0..m.pos.len()).step_by(3) {
            let v: Vec<[f32; 3]> = (0..3).map(|k| rot(m.pos[t + k])).collect();
            let sc: Vec<[f32; 3]> = v.iter().map(|p| [ox + half + p[0] * s, half - p[1] * s, p[2]]).collect();
            let col: Vec<[f32; 3]> = (0..3).map(|k| shade(m, t + k, &rot, 0.8)).collect();
            let (x0, x1) = (sc.iter().map(|p| p[0]).fold(f32::MAX, f32::min).floor().max(ox) as usize, sc.iter().map(|p| p[0]).fold(f32::MIN, f32::max).ceil().min(ox + SPRITE as f32 - 1.0) as usize);
            let (y0, y1) = (sc.iter().map(|p| p[1]).fold(f32::MAX, f32::min).floor().max(0.0) as usize, sc.iter().map(|p| p[1]).fold(f32::MIN, f32::max).ceil().min(h as f32 - 1.0) as usize);
            let area = (sc[1][0] - sc[0][0]) * (sc[2][1] - sc[0][1]) - (sc[2][0] - sc[0][0]) * (sc[1][1] - sc[0][1]);
            if area.abs() < 1e-6 {
                continue;
            }
            for y in y0..=y1 {
                for x in x0..=x1 {
                    let (fx, fy) = (x as f32 + 0.5, y as f32 + 0.5);
                    let e = |a: [f32; 3], b: [f32; 3]| (b[0] - a[0]) * (fy - a[1]) - (b[1] - a[1]) * (fx - a[0]);
                    let (w0, w1, w2) = (e(sc[1], sc[2]) / area, e(sc[2], sc[0]) / area, e(sc[0], sc[1]) / area);
                    if w0 < 0.0 || w1 < 0.0 || w2 < 0.0 {
                        continue;
                    }
                    let z = w0 * sc[0][2] + w1 * sc[1][2] + w2 * sc[2][2];
                    let o = y * w + x;
                    if z <= zb[o] {
                        continue;
                    }
                    zb[o] = z;
                    for k in 0..3 {
                        px[o * 4 + k] = ((w0 * col[0][k] + w1 * col[1][k] + w2 * col[2][k]).clamp(0.0, 1.0) * 255.0) as u8;
                    }
                    px[o * 4 + 3] = 255;
                }
            }
        }
    }
    Some((w, h, px))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn models_decode_and_sprites_cover() {
        let ms = models();
        assert_eq!(ms.len(), MODEL_COUNT);
        for (i, m) in ms.iter().enumerate() {
            assert!(m.pos.len() >= 60 && m.pos.len() % 3 == 0, "model {i}: {} vertices", m.pos.len());
            assert!(m.pos.iter().all(|p| p.iter().all(|v| v.abs() <= 0.51)));
        }
        // the red body is red, the blue body blue (the atlas rows land where make_drives.py put them)
        let avg = |m: &Baked| m.base.iter().fold([0.0f32; 3], |a, c| [a[0] + c[0], a[1] + c[1], a[2] + c[2]]);
        let (r, b) = (avg(&ms[0]), avg(&ms[2]));
        assert!(r[0] > r[2] && b[2] > b[0], "red {r:?} blue {b:?}");
        let (w, h, px) = sprite_sheet(0).unwrap();
        assert_eq!((w, h), (SPRITE * SPRITE_FRAMES, SPRITE));
        let cover = px.chunks(4).filter(|p| p[3] != 0).count();
        assert!(cover > w * h / 12, "coverage {cover}");
    }

    #[test]
    fn list_commits() {
        begin();
        assert!(push(Inst::Fx { kind: FX_RING, at: [0.0; 3], a: 5.0, b: 1.0, c: 0.0, rgba: 0xFFFF_FFFF }));
        commit();
        assert_eq!(shown(), 1);
        begin();
        commit();
        assert_eq!(shown(), 0);
    }
}
